CORPUS = [
 {"id":"G1","topic":"rotterdam","source":"Rotterdam 2003 (paraphrased)",
  "text":"PCOS is diagnosed when at least two of three features are present: oligo-ovulation or anovulation, clinical or biochemical hyperandrogenism, and polycystic ovaries on ultrasound, after other causes are excluded."},
 {"id":"G2","topic":"pcom","source":"Rotterdam 2003 (paraphrased)",
  "text":"Polycystic ovarian morphology in 2003 was defined as 12 or more follicles of 2-9 mm in at least one ovary, or ovarian volume above 10 mL."},
 {"id":"G3","topic":"pcom","source":"International guideline 2018/2023 (paraphrased)",
  "text":"With modern high-frequency transvaginal probes (8 MHz or higher), the follicle number threshold is 20 or more per ovary, or ovarian volume of 10 mL or more. Follicles are counted across the whole ovary."},
 {"id":"G4","topic":"pcom","source":"International guideline 2023 (paraphrased)",
  "text":"In adults, serum anti-Mullerian hormone (AMH) can be used as an alternative to ultrasound for the polycystic ovarian morphology criterion."},
 {"id":"G5","topic":"adolescent","source":"International guideline 2018/2023 (paraphrased)",
  "text":"Ultrasound is not recommended for PCOS diagnosis within 8 years of menarche because multifollicular ovaries are common in adolescents."},
 {"id":"G6","topic":"ovulation","source":"International guideline (paraphrased)",
  "text":"Irregular cycles are cycles shorter than 21 or longer than 35 days, or fewer than 8 cycles per year. Irregularity is normal in the first year after menarche."},
 {"id":"G7","topic":"androgen","source":"International guideline (paraphrased)",
  "text":"Clinical hyperandrogenism is assessed mainly by hirsutism using a modified Ferriman-Gallwey score. Biochemical hyperandrogenism uses total or free testosterone. Acne and androgenic alopecia are weaker evidence."},
 {"id":"G8","topic":"exclusion","source":"Rotterdam 2003 (paraphrased)",
  "text":"Other causes must be excluded before diagnosis: thyroid disease (check TSH), hyperprolactinaemia (check prolactin), non-classic congenital adrenal hyperplasia, Cushing syndrome and androgen-secreting tumours."},
 {"id":"G9","topic":"labs","source":"General clinical practice (paraphrased)",
  "text":"LH to FSH ratio and AMH are supportive findings but are not diagnostic on their own. AMH is often higher in PCOS."},
 {"id":"G10","topic":"safety","source":"Decision-support practice (paraphrased)",
  "text":"Automated outputs should support, not replace, clinical judgement. Conflicting, borderline or incomplete findings should be reviewed by a physician before any diagnosis is communicated."},
]
